/** Generated by scaffold-crud-pages. Query hooks for PointsLedger.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchPointsLedgerList,
  fetchPointsLedgerById,
  createPointsLedger,
  updatePointsLedger,
  deletePointsLedger,
  type FetchPointsLedgerListParams,
} from '~/services/httpServices/pointsLedgerService';
import type { CreatePointsLedgerRequest, UpdatePointsLedgerRequest } from '~/types/points-ledger';

const DOMAIN = 'pointsLedger';

export function usePointsLedgerList(params?: FetchPointsLedgerListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchPointsLedgerList(params),
  });
}

export function usePointsLedger(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchPointsLedgerById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreatePointsLedger() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreatePointsLedgerRequest) => createPointsLedger(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdatePointsLedger() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdatePointsLedgerRequest }) =>
      updatePointsLedger(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeletePointsLedger() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deletePointsLedger(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
